public protocol EngineProtocol: AnyObject, Sendable {
    
    /**
     * A library card picture: footage, shader backgrounds, stills, overlays, text styles.
     */
    func assetThumb(id: String)  -> MediaFrame?
    
    /**
     * A clip's loudness for drawing its waveform: `buckets` peak levels (0–1) across the clip.
     */
    func audioPeaks(clipId: String, buckets: UInt32)  -> [Float]
    
    /**
     * A finger drag, pinch or twist on the preview starts: the edits until `end_gesture` are
     * one undo step.
     */
    func beginGesture() 
    
    /**
     * Run a Liemo tool (the MCP tools: list_projects, create_project, add_clip, update_clip,
     * apply_effect, set_transition, render_frame, undo…). `args_json` is a JSON object.
     */
    func call(tool: String, argsJson: String)  -> ToolResult
    
    func canRedo()  -> Bool
    
    func canUndo()  -> Bool
    
    /**
     * A clip's box on the picture at `time`, in canvas units: centre x, centre y, width, height,
     * rotation (degrees), and the point it scales and turns about (x, y). Empty when it isn't a
     * picture clip.
     */
    func clipBox(clipId: String, time: Double)  -> [Double]
    
    /**
     * Save, refresh the project's thumbnail and close it.
     */
    func closeProject() 
    
    func deleteProject(id: String)  -> Bool
    
    /**
     * The copy's id.
     */
    func duplicateProject(id: String)  -> String?
    
    func effectThumb(id: String)  -> MediaFrame
    
    func endGesture() 
    
    /**
     * The clip under a point on the picture (canvas units from its top-left), front-most first.
     */
    func hitTest(time: Double, x: Double, y: Double)  -> String?
    
    /**
     * Installed font families on this device.
     */
    func installedFonts()  -> [String]
    
    /**
     * What the AI is told about Liemo.
     */
    func instructions()  -> String
    
    /**
     * Open a project for editing; returns its JSON (as get_project shows it).
     */
    func openProject(id: String)  -> ToolResult
    
    /**
     * Where a project's thumbnail JPEG is (it may not exist yet).
     */
    func projectThumbPath(id: String)  -> String
    
    /**
     * `frames` of the open project's sound from `start` seconds: 48 kHz interleaved stereo.
     */
    func renderAudio(start: Double, frames: UInt32)  -> [Float]
    
    /**
     * The open project's whole mix from `start` to `stop` seconds (48 kHz interleaved stereo),
     * for export.
     */
    func renderAudioRange(start: Double, stop: Double)  -> [Float]
    
    /**
     * One clip of the open project alone at `time` (its effects and motion, nothing else), on
     * a transparent frame: freeze frames.
     */
    func renderClip(clipId: String, time: Double, max: UInt32)  -> MediaFrame?
    
    /**
     * The open project's frame at `time`, its long side at most `max` px.
     */
    func renderFrame(time: Double, max: UInt32)  -> MediaFrame?
    
    /**
     * The frame without one clip: what stays still while a finger moves that clip.
     */
    func renderFrameWithout(clipId: String, time: Double, max: UInt32)  -> MediaFrame?
    
    /**
     * What's said, for captions: the sound of `start`..`stop` without the music (built-in tracks
     * and anything on the Music track), 48 kHz interleaved stereo. Music under a voice is what
     * most often makes speech recognition give up.
     */
    func renderVoiceRange(start: Double, stop: Double)  -> [Float]
    
    /**
     * A text style drawn on a dark card (`props_json`: the text fields as get_project shows
     * them), for the style gallery.
     */
    func textPreview(propsJson: String, width: UInt32, height: UInt32)  -> MediaFrame?
    
    /**
     * The tools, as MCP tool definitions (name, description, inputSchema), for Liemo AI.
     */
    func toolDefinitions()  -> String
    
    func transitionThumb(id: String)  -> MediaFrame
    
    func version()  -> String
    
}
