/**
 * What the app does for the engine with AVFoundation and Image I/O.
 */
public protocol MediaHost: AnyObject, Sendable {
    
    /**
     * Length, size and streams of a video or audio file.
     */
    func probe(path: String)  -> MediaProbe?
    
    /**
     * The video picture at `time` seconds, fitting in `max_w`×`max_h`.
     */
    func videoFrame(path: String, time: Double, maxW: UInt32, maxH: UInt32)  -> MediaFrame?
    
    /**
     * A picture the engine can't decode itself (HEIC…), long side at most `max`.
     */
    func decodeImage(path: String, max: UInt32)  -> MediaFrame?
    
    /**
     * The file's sound as 48 kHz interleaved stereo.
     */
    func decodeAudio(path: String)  -> [Float]?
    
    /**
     * Where the subject is in a picture (people, pets, things in front): a mask whose alpha
     * is 255 on the subject and 0 behind it, at any size. None when nothing stands out.
     */
    func segment(frame: MediaFrame)  -> MediaFrame?
    
}
/**
 * What the app does for the engine with AVFoundation and Image I/O.
 */
open class MediaHostImpl: MediaHost, @unchecked Sendable {
    fileprivate let handle: UInt64

    /// Used to instantiate a [FFIObject] without an actual handle, for fakes in tests, mostly.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public struct NoHandle {
        public init() {}
    }

    // TODO: We'd like this to be `private` but for Swifty reasons,
    // we can't implement `FfiConverter` without making this `required` and we can't
    // make it `required` without making it `public`.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    required public init(unsafeFromHandle handle: UInt64) {
        self.handle = handle
    }

    // This constructor can be used to instantiate a fake object.
    // - Parameter noHandle: Placeholder value so we can have a constructor separate from the default empty one that may be implemented for classes extending [FFIObject].
    //
    // - Warning:
    //     Any object instantiated with this constructor cannot be passed to an actual Rust-backed object. Since there isn't a backing handle the FFI lower functions will crash.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public init(noHandle: NoHandle) {
        self.handle = 0
    }

#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public func uniffiCloneHandle() -> UInt64 {
        return try! rustCall { uniffi_liemo_mobile_fn_clone_mediahost(self.handle, $0) }
    }
    // No primary constructor declared for this class.

    deinit {
        if handle == 0 {
            // Mock objects have handle=0 don't try to free them
            return
        }

        try! rustCall { uniffi_liemo_mobile_fn_free_mediahost(handle, $0) }
    }

    

    
    /**
     * Length, size and streams of a video or audio file.
     */
open func probe(path: String) -> MediaProbe?  {
    return try!  FfiConverterOptionTypeMediaProbe.lift(try! rustCall() {
        uniffiCallStatus in
    uniffi_liemo_mobile_fn_method_mediahost_probe(
            self.uniffiCloneHandle(),
        FfiConverterString.lower(path),uniffiCallStatus
    )
})
}
    
