// Put the implementation in a struct so we don't pollute the top-level namespace
fileprivate struct UniffiCallbackInterfaceMediaHost {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    //
    // Store the vtable directly.
    static let vtable: UniffiVTableCallbackInterfaceMediaHost = UniffiVTableCallbackInterfaceMediaHost(
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            do {
                try FfiConverterTypeMediaHost.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface MediaHost: handle missing in uniffiFree")
            }
        },
        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterTypeMediaHost.handleMap.clone(handle: uniffiHandle)
            } catch {
                fatalError("Uniffi callback interface MediaHost: handle missing in uniffiClone")
            }
        },
        probe: { (
            uniffiHandle: UInt64,
            path: RustBuffer,
            uniffiOutReturn: UnsafeMutablePointer<RustBuffer>,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> MediaProbe? in
                guard let uniffiObj = try? FfiConverterTypeMediaHost.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return uniffiObj.probe(
                     path: try FfiConverterString.lift(path)
                )
            }

            
            let writeReturn = { uniffiOutReturn.pointee = FfiConverterOptionTypeMediaProbe.lower($0) }
            uniffiTraitInterfaceCall(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn
            )
        },
        videoFrame: { (
            uniffiHandle: UInt64,
            path: RustBuffer,
            time: Double,
            maxW: UInt32,
            maxH: UInt32,
            uniffiOutReturn: UnsafeMutablePointer<RustBuffer>,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> MediaFrame? in
                guard let uniffiObj = try? FfiConverterTypeMediaHost.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return uniffiObj.videoFrame(
                     path: try FfiConverterString.lift(path),
                     time: try FfiConverterDouble.lift(time),
                     maxW: try FfiConverterUInt32.lift(maxW),
                     maxH: try FfiConverterUInt32.lift(maxH)
                )
            }

            
            let writeReturn = { uniffiOutReturn.pointee = FfiConverterOptionTypeMediaFrame.lower($0) }
            uniffiTraitInterfaceCall(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn
            )
        },
        decodeImage: { (
            uniffiHandle: UInt64,
            path: RustBuffer,
            max: UInt32,
            uniffiOutReturn: UnsafeMutablePointer<RustBuffer>,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> MediaFrame? in
                guard let uniffiObj = try? FfiConverterTypeMediaHost.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return uniffiObj.decodeImage(
                     path: try FfiConverterString.lift(path),
                     max: try FfiConverterUInt32.lift(max)
                )
            }

            
            let writeReturn = { uniffiOutReturn.pointee = FfiConverterOptionTypeMediaFrame.lower($0) }
            uniffiTraitInterfaceCall(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn
            )
        },
        decodeAudio: { (
            uniffiHandle: UInt64,
            path: RustBuffer,
            uniffiOutReturn: UnsafeMutablePointer<RustBuffer>,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> [Float]? in
                guard let uniffiObj = try? FfiConverterTypeMediaHost.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return uniffiObj.decodeAudio(
                     path: try FfiConverterString.lift(path)
                )
            }

            
            let writeReturn = { uniffiOutReturn.pointee = FfiConverterOptionSequenceFloat.lower($0) }
            uniffiTraitInterfaceCall(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn
            )
        },
        segment: { (
            uniffiHandle: UInt64,
            frame: RustBuffer,
            uniffiOutReturn: UnsafeMutablePointer<RustBuffer>,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> MediaFrame? in
                guard let uniffiObj = try? FfiConverterTypeMediaHost.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return uniffiObj.segment(
                     frame: try FfiConverterTypeMediaFrame_lift(frame)
                )
            }

            
            let writeReturn = { uniffiOutReturn.pointee = FfiConverterOptionTypeMediaFrame.lower($0) }
            uniffiTraitInterfaceCall(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn
            )
        }
    )

    // Rust stores this pointer for future callback invocations, so it must live
    // for the process lifetime (not just for the init function call).
    //
    // `nonisolated(unsafe)` is needed under Swift 6 strict concurrency.
    // This is safe because the pointee is initialized once during static init
    // and never mutated by either side of the FFI.  Its fields are C function pointers.
    nonisolated(unsafe) static let vtablePtr: UnsafePointer<UniffiVTableCallbackInterfaceMediaHost> = {
        let ptr = UnsafeMutablePointer<UniffiVTableCallbackInterfaceMediaHost>.allocate(capacity: 1)
        ptr.initialize(to: vtable)
        return UnsafePointer(ptr)
    }()
}

private func uniffiCallbackInitMediaHost() {
    uniffi_liemo_mobile_fn_init_callback_vtable_mediahost(UniffiCallbackInterfaceMediaHost.vtablePtr)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeMediaHost: FfiConverter {
    fileprivate static let handleMap = UniffiHandleMap<MediaHost>()

    typealias FfiType = UInt64
    typealias SwiftType = MediaHost

    public static func lift(_ handle: UInt64) throws -> MediaHost {
        if ((handle & 1) == 0) {
            // Rust-generated handle, construct a new class that uses the handle to implement the
            // interface
            return MediaHostImpl(unsafeFromHandle: handle)
        } else {
            // Swift-generated handle, get the object from the handle map
            return try handleMap.remove(handle: handle)
        }
    }

    public static func lower(_ value: MediaHost) -> UInt64 {
         if let rustImpl = value as? MediaHostImpl {
             // Rust-implemented object.  Clone the handle and return it
